            PreparedStatement psmt = conn.prepareStatement("SELECT * FROM users WHERE username = '" + username + "' AND password = '" + password + "'");
            psmt.executeQuery();
            // Potential SQL Injection point here.
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
